using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;
using RaceDay.API.Controllers;
using RaceDay.API.DTOs;
using RaceDay.Core.Models;
using RaceDay.Infrastructure.Data;

namespace Race_Day_Part_2.Test
{
    public class AuthControllerTests
    {
        private AppDbContext GetInMemoryDbContext(string dbName)
        {
            var options = new DbContextOptionsBuilder<AppDbContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;

            return new AppDbContext(options);
        }

        [Fact]
        public void Register_ValidUser_ReturnsOkStatus()
        {
            // Arrange
            using var context = GetInMemoryDbContext("Register_Success_DB");
            var controller = new AuthController();

            // Added the 4th parameter ("Participant") to match your exact RegisterDto constructor signature
            var registrationDto = new RegisterDto("Test Participant", "participant@raceday.com", "Password123!", "Participant");

            // Act
            var result = controller.Register(registrationDto);

            // Assert
            var okResult = Assert.IsType<OkObjectResult>(result);
            Assert.Equal(200, okResult.StatusCode);
        }

        [Fact]
        public void Register_DuplicateEmail_ReturnsBadRequestStatus()
        {
            // Arrange
            using var context = GetInMemoryDbContext("Register_Duplicate_DB");

            var existingUser = new User
            {
                Id = 1,
                Name = "Existing User",
                Email = "duplicate@raceday.com",
                PasswordHash = BCrypt.Net.BCrypt.HashPassword("Password123"),
                Role = "Organiser"
            };
            context.Users.Add(existingUser);
            context.SaveChanges();

            var controller = new AuthController();

            // Added the 4th parameter ("Participant") here as well
            var duplicateDto = new RegisterDto("New User", "duplicate@raceday.com", "Password123!", "Participant");

            // Act
            var result = controller.Register(duplicateDto);

            // Assert
            var badRequestResult = Assert.IsType<BadRequestObjectResult>(result);
            Assert.Equal(400, badRequestResult.StatusCode);
        }
    }
}
